// Complete modular project files mapping
export const MODULAR_FILES: Record<string, string> = {
  "platformio.ini": "; PlatformIO Project Configuration for ESP32-C3 Music Receiver\n; Specially configured for ESP32-C3 SuperMini + UDA1334A DAC + SSD1306 0.42\" OLED\n\n[platformio]\ndefault_envs = esp32c3\n\n[env:esp32c3]\nplatform = espressif32 @ ^6.5.0\nboard = esp32-c3-devkitm-1\nframework = arduino\nmonitor_speed = 115200\nupload_speed = 921600\n\n; Flash and memory tuning for ESP32-C3 4MB\nboard_build.flash_mode = dio\nboard_build.partitions = min_spiffs.csv\n\nbuild_flags =\n    -DCORE_DEBUG_LEVEL=0\n    -DARDUINO_USB_CDC_ON_BOOT=1\n    -DARDUINO_USB_MODE=1\n    -O2\n\nlib_deps =\n    olikraus/U8g2 @ ^2.35.19\n",
  ".github/workflows/build.yml": "name: ESP32-C3 PlatformIO CI Build\n\non:\n  push:\n    branches: [ main, master ]\n  pull_request:\n    branches: [ main, master ]\n  workflow_dispatch:\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout Code\n        uses: actions/checkout@v4\n\n      - name: Cache PlatformIO packages\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/.platformio\n            .pio\n          key: ${{ runner.os }}-pio-${{ hashFiles('**/platformio.ini') }}\n          restore-keys: |\n            ${{ runner.os }}-pio-\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n\n      - name: Install PlatformIO\n        run: |\n          python -m pip install --upgrade pip\n          pip install platformio\n\n      - name: Compile ESP32-C3 Firmware\n        run: platformio run\n\n      - name: Upload Firmware Binary Artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: C3-Music-Firmware-bin\n          path: .pio/build/esp32c3/firmware.bin\n          if-no-files-found: error\n",
  "include/config.h": "#pragma once\n\n#include <Arduino.h>\n#include <IPAddress.h>\n\n// Device Metadata\n#define DEVICE_NAME       \"C3 Music Receiver\"\n#define MDNS_HOSTNAME     \"c3music\"\n#define FIRMWARE_VERSION  \"2.0.0\"\n\n// Hardware Pin Configuration\n// I2S connections for UDA1334A DAC (Only 3 wires needed: BCK, WSEL, DIN)\nconstexpr int PIN_I2S_BCLK  = 3;   // Bit Clock\nconstexpr int PIN_I2S_LRCLK = 1;   // Word Select / LRCK\nconstexpr int PIN_I2S_DOUT  = 10;  // Serial Data Out (connects to DIN)\n\n// I2C connections for 0.42\" OLED (SSD1306 72x40)\nconstexpr uint8_t PIN_I2C_SDA  = 5;\nconstexpr uint8_t PIN_I2C_SCL  = 6;\nconstexpr uint8_t OLED_WIDTH   = 72;\nconstexpr uint8_t OLED_HEIGHT  = 40;\n\n// Network Defaults\nstatic const char DEFAULT_WIFI_SSID[] = \"GFiber_2.4_Coverage_AECD9\";\nstatic const char DEFAULT_WIFI_PASS[] = \"006BF4FD\";\nstatic const char DEFAULT_PHONE_HOST[] = \"192.168.254.119\";\n\nconstexpr uint16_t DEFAULT_TCP_PORT  = 50005; // Raw PCM (Zero latency)\nconstexpr uint16_t DEFAULT_HTTP_PORT = 8080;  // HTTP WAV Server\n\n// Audio & Ring Buffer Parameters\nconstexpr uint32_t DEFAULT_SAMPLE_RATE     = 44100;\nconstexpr uint8_t  DEFAULT_CHANNELS        = 2;\nconstexpr uint8_t  DEFAULT_BITS_PER_SAMPLE = 16;\nconstexpr size_t   AUDIO_RING_BYTES        = 65536;\nconstexpr size_t   NETWORK_READ_CHUNK      = 1460;\nconstexpr size_t   I2S_DMA_CHUNK           = 1024;\nconstexpr uint32_t STREAM_RETRY_INTERVAL_MS = 2000;\nconstexpr uint32_t WIFI_RETRY_INTERVAL_MS   = 8000;\n\n// Enums\nenum StreamMode : uint8_t {\n  STREAM_MODE_TCP = 0,\n  STREAM_MODE_HTTP = 1\n};\n\nenum ReceiverState : uint8_t {\n  RX_BOOTING = 0,\n  RX_WIFI_CONNECTING,\n  RX_WIFI_OFFLINE,\n  RX_IDLE,\n  RX_CONNECTING,\n  RX_BUFFERING,\n  RX_STREAMING,\n  RX_STOPPED,\n  RX_ERROR,\n  RX_UPDATING\n};\n\nstruct StreamFormat {\n  uint32_t sampleRate = DEFAULT_SAMPLE_RATE;\n  uint16_t channels = DEFAULT_CHANNELS;\n  uint16_t bitsPerSample = DEFAULT_BITS_PER_SAMPLE;\n  uint16_t audioFormat = 1;\n  bool valid = false;\n};\n\nstruct RuntimeStats {\n  uint32_t reconnects = 0;\n  uint32_t underruns = 0;\n  uint32_t streamErrors = 0;\n  uint32_t bytesReceived = 0;\n  uint32_t bytesPlayed = 0;\n  uint32_t sessionStartedMs = 0;\n  uint32_t lastReceiveMs = 0;\n  int lastHttpStatus = 0;\n  String lastError = \"\";\n};\n\nstruct AppSettings {\n  String phoneHost = DEFAULT_PHONE_HOST;\n  uint16_t tcpPort = DEFAULT_TCP_PORT;\n  uint16_t httpPort = DEFAULT_HTTP_PORT;\n  StreamMode preferredMode = STREAM_MODE_TCP;\n  bool autoFallback = true;\n  bool autoReconnect = true;\n  bool autoDiscover = true;\n  bool oledEnabled = true;\n  bool streamEnabled = true;\n  uint16_t targetBufferMs = 180;\n};\n",
  "include/audio_i2s.h": "#pragma once\n\n#include \"config.h\"\n#include <driver/i2s.h>\n#include <freertos/FreeRTOS.h>\n#include <freertos/semphr.h>\n\nclass AudioI2S {\npublic:\n  static AudioI2S& instance();\n\n  bool begin(uint32_t sampleRate, uint16_t channels, uint16_t bitsPerSample = 16);\n  void end();\n  bool isReady() const { return _ready; }\n\n  // Plays a crisp 440Hz test beep to confirm hardware DAC wiring\n  void playTestTone(uint32_t durationMs = 400);\n\n  // Writes PCM samples directly to I2S DMA FIFO\n  size_t writeSamples(const uint8_t* data, size_t length, uint32_t timeoutTicks = 40);\n\n  // Expands mono 16-bit to stereo 16-bit and writes\n  size_t writeMonoAsStereo(const uint8_t* monoData, size_t length, uint32_t timeoutTicks = 40);\n\n  void clearDmaBuffer();\n\nprivate:\n  AudioI2S();\n  ~AudioI2S();\n\n  bool _ready;\n  SemaphoreHandle_t _mutex;\n  uint8_t _stereoExpandBuffer[I2S_DMA_CHUNK * 2];\n};\n",
  "include/audio_ringbuf.h": "#pragma once\n\n#include \"config.h\"\n#include <freertos/FreeRTOS.h>\n#include <freertos/semphr.h>\n\nclass AudioRingBuffer {\npublic:\n  static AudioRingBuffer& instance();\n\n  bool write(const uint8_t* data, size_t length);\n  size_t read(uint8_t* destination, size_t maxLen);\n  void clear();\n\n  size_t available() const;\n  size_t freeSpace() const;\n  uint8_t percentFull() const;\n\n  SemaphoreHandle_t dataSemaphore() const { return _dataSemaphore; }\n\nprivate:\n  AudioRingBuffer();\n  ~AudioRingBuffer();\n\n  uint8_t _buffer[AUDIO_RING_BYTES];\n  volatile size_t _readIndex;\n  volatile size_t _writeIndex;\n  volatile size_t _count;\n  portMUX_TYPE _mux;\n  SemaphoreHandle_t _dataSemaphore;\n};\n",
  "include/display_oled.h": "#pragma once\n\n#include \"config.h\"\n#include <U8g2lib.h>\n\nclass DisplayOLED {\npublic:\n  static DisplayOLED& instance();\n\n  void begin();\n  void update(ReceiverState state, const StreamFormat& format, uint8_t bufferPercent, const String& error = \"\");\n  void setEnabled(bool enabled);\n  bool isEnabled() const { return _enabled; }\n  void setVuLevel(uint8_t level) { _vuLevel = level; }\n\nprivate:\n  DisplayOLED();\n  void drawCentered(const char* text, uint8_t y, const uint8_t* font);\n\n  U8G2_SSD1306_72X40_ER_F_HW_I2C _u8g2;\n  bool _available;\n  bool _enabled;\n  uint8_t _vuLevel;\n  uint32_t _lastRenderMs;\n};\n",
  "include/web_assets.h": "#pragma once\n\n#include <Arduino.h>\n\nstatic const char HTML_INDEX[] PROGMEM = R\"rawliteral(\n<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#000000\">\n  <title>C3 Music</title>\n  <style>\n    :root {\n      --bg: #000000;\n      --surface: #111215;\n      --surface-elevated: #181a1f;\n      --surface-high: #21242b;\n      --border: rgba(255, 255, 255, 0.08);\n      --text: #e6e1e5;\n      --text-muted: #95909a;\n      --primary: #d0bcff;\n      --primary-container: #381e72;\n      --on-primary: #1d0160;\n      --accent: #c4b0f0;\n      --success: #a8dab5;\n      --warning: #fce18a;\n      --danger: #f2b8b5;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }\n    body {\n      background: var(--bg);\n      color: var(--text);\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Google Sans\", sans-serif;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      padding-bottom: 84px;\n    }\n    header {\n      position: sticky;\n      top: 0;\n      z-index: 30;\n      background: rgba(0, 0, 0, 0.92);\n      backdrop-filter: blur(16px);\n      border-bottom: 1px solid var(--border);\n      padding: 14px 20px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    .brand { font-size: 17px; font-weight: 700; letter-spacing: -0.01em; color: var(--text); }\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      font-size: 11px;\n      font-weight: 600;\n      padding: 4px 10px;\n      border-radius: 999px;\n      background: var(--surface-elevated);\n      border: 1px solid var(--border);\n      color: var(--text-muted);\n    }\n    .badge.ok { color: var(--success); border-color: rgba(168, 218, 181, 0.25); background: rgba(168, 218, 181, 0.08); }\n    .badge.warn { color: var(--warning); border-color: rgba(252, 225, 138, 0.25); background: rgba(252, 225, 138, 0.08); }\n    .badge.err { color: var(--danger); border-color: rgba(242, 184, 181, 0.25); background: rgba(242, 184, 181, 0.08); }\n    \n    main { max-width: 620px; width: 100%; margin: 0 auto; padding: 18px 16px; flex: 1; }\n    .tab-content { display: none; }\n    .tab-content.active { display: block; animation: fadeIn 0.2s ease; }\n    @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }\n\n    .card {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 24px;\n      padding: 20px;\n      margin-bottom: 16px;\n    }\n    .card-title { font-size: 14px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; margin-bottom: 14px; }\n    \n    /* Now Playing Visuals */\n    .player-hero {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      text-align: center;\n      padding: 16px 0 24px;\n    }\n    .disc-container {\n      width: 88px;\n      height: 88px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #1f2229 0%, #0e1014 100%);\n      border: 2px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      margin-bottom: 18px;\n      box-shadow: 0 10px 30px rgba(0,0,0,0.6);\n    }\n    .disc-inner {\n      width: 32px;\n      height: 32px;\n      border-radius: 50%;\n      background: var(--primary-container);\n      border: 2px solid rgba(255,255,255,0.15);\n    }\n    .track-status { font-size: 24px; font-weight: 700; color: #fff; margin-bottom: 4px; }\n    .track-meta { font-size: 13px; color: var(--text-muted); font-variant-numeric: tabular-nums; }\n    \n    /* Subtle Level Bars */\n    .vu-meter {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 4px;\n      height: 28px;\n      margin: 16px 0;\n    }\n    .vu-bar {\n      width: 4px;\n      height: 6px;\n      background: var(--primary);\n      opacity: 0.4;\n      border-radius: 2px;\n      transition: height 0.15s ease, opacity 0.15s ease;\n    }\n    .active-play .vu-bar { opacity: 0.9; }\n\n    /* Buffer Progress */\n    .buffer-track {\n      background: var(--surface-high);\n      height: 8px;\n      border-radius: 999px;\n      overflow: hidden;\n      margin: 10px 0 6px;\n    }\n    .buffer-fill {\n      height: 100%;\n      width: 0%;\n      background: var(--primary);\n      border-radius: 999px;\n      transition: width 0.25s ease;\n    }\n\n    /* Key-Value Rows */\n    .row {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 11px 0;\n      border-bottom: 1px solid rgba(255,255,255,0.04);\n      font-size: 13px;\n    }\n    .row:last-child { border-bottom: none; }\n    .row-label { color: var(--text-muted); }\n    .row-val { font-weight: 500; color: var(--text); font-variant-numeric: tabular-nums; }\n\n    /* Buttons */\n    .btn-group { display: flex; gap: 10px; margin-top: 14px; }\n    button {\n      flex: 1;\n      height: 44px;\n      border-radius: 999px;\n      font-size: 13px;\n      font-weight: 600;\n      border: 1px solid var(--border);\n      background: var(--surface-elevated);\n      color: var(--text);\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      transition: background 0.15s;\n    }\n    button:active { transform: scale(0.98); }\n    button.primary {\n      background: var(--primary);\n      color: var(--on-primary);\n      border: none;\n    }\n    button.danger {\n      background: rgba(242, 184, 181, 0.12);\n      color: var(--danger);\n      border-color: rgba(242, 184, 181, 0.3);\n    }\n\n    /* Form Fields */\n    .field { margin-bottom: 14px; }\n    .field label { display: block; font-size: 12px; color: var(--text-muted); margin-bottom: 6px; }\n    input[type=\"text\"], input[type=\"number\"], select {\n      width: 100%;\n      height: 44px;\n      background: #08080a;\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: 0 14px;\n      color: var(--text);\n      font-size: 14px;\n      font-family: inherit;\n    }\n    input:focus, select:focus {\n      outline: none;\n      border-color: var(--primary);\n    }\n    .switch-row {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 12px 0;\n    }\n    input[type=\"range\"] {\n      width: 100%;\n      accent-color: var(--primary);\n      margin: 8px 0;\n    }\n    .switch {\n      position: relative;\n      width: 46px;\n      height: 26px;\n      appearance: none;\n      background: #252830;\n      border-radius: 999px;\n      cursor: pointer;\n      outline: none;\n      transition: background 0.2s;\n    }\n    .switch:checked { background: var(--primary); }\n    .switch::before {\n      content: '';\n      position: absolute;\n      width: 20px;\n      height: 20px;\n      border-radius: 50%;\n      top: 3px;\n      left: 3px;\n      background: #fff;\n      transition: transform 0.2s;\n    }\n    .switch:checked::before {\n      transform: translateX(20px);\n      background: var(--on-primary);\n    }\n\n    /* Fixed Bottom Nav (4 Tabs) */\n    nav {\n      position: fixed;\n      bottom: 0;\n      left: 0;\n      right: 0;\n      z-index: 40;\n      background: rgba(0, 0, 0, 0.96);\n      backdrop-filter: blur(20px);\n      border-top: 1px solid var(--border);\n      display: flex;\n      height: 68px;\n      padding-bottom: env(safe-area-inset-bottom);\n    }\n    .nav-btn {\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      background: transparent;\n      border: none;\n      border-radius: 0;\n      color: var(--text-muted);\n      font-size: 11px;\n      font-weight: 500;\n      gap: 3px;\n    }\n    .nav-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n    .nav-btn.active { color: var(--primary); font-weight: 700; }\n    .nav-btn.active svg { stroke: var(--primary); }\n\n    /* Toast */\n    #toast {\n      position: fixed;\n      bottom: 84px;\n      left: 50%;\n      transform: translateX(-50%) translateY(20px);\n      background: var(--surface-high);\n      color: var(--text);\n      border: 1px solid var(--border);\n      padding: 10px 18px;\n      border-radius: 999px;\n      font-size: 13px;\n      opacity: 0;\n      pointer-events: none;\n      transition: all 0.25s ease;\n      z-index: 50;\n      box-shadow: 0 8px 24px rgba(0,0,0,0.5);\n    }\n    #toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n  </style>\n</head>\n<body>\n\n  <!-- Top Bar -->\n  <header>\n    <div class=\"brand\">C3 Music</div>\n    <div class=\"badge\" id=\"stateBadge\">\n      <span id=\"stateDot\">\u25cf</span>\n      <span id=\"stateText\">Ready</span>\n    </div>\n  </header>\n\n  <!-- 4 Main App Tabs -->\n  <main>\n    <!-- TAB 1: NOW PLAYING -->\n    <div class=\"tab-content active\" id=\"tab-now\">\n      <div class=\"card player-hero\">\n        <div class=\"disc-container\">\n          <div class=\"disc-inner\"></div>\n        </div>\n        <div class=\"track-status\" id=\"heroStatus\">Ready</div>\n        <div class=\"track-meta\" id=\"heroMeta\">Waiting for audio stream</div>\n\n        <div class=\"vu-meter\" id=\"vuMeter\">\n          <div class=\"vu-bar\" style=\"height: 12px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 18px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 24px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 16px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 22px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 14px;\"></div>\n          <div class=\"vu-bar\" style=\"height: 20px;\"></div>\n        </div>\n\n        <div style=\"width: 100%; margin-top: 8px;\">\n          <div style=\"display: flex; justify-content: space-between; font-size: 11px; color: var(--text-muted);\">\n            <span>Buffer Occupancy</span>\n            <span id=\"bufPercentText\">0%</span>\n          </div>\n          <div class=\"buffer-track\">\n            <div class=\"buffer-fill\" id=\"bufBar\"></div>\n          </div>\n        </div>\n\n        <div class=\"btn-group\" style=\"width: 100%; margin-top: 20px;\">\n          <button class=\"primary\" onclick=\"postAction('/api/stream/start')\">Start</button>\n          <button onclick=\"postAction('/api/stream/stop')\">Stop</button>\n          <button onclick=\"postAction('/api/stream/reconnect')\">Reconnect</button>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-title\">Stream Telemetry</div>\n        <div class=\"row\">\n          <span class=\"row-label\">Mode / Host</span>\n          <span class=\"row-val\" id=\"teleHost\">\u2014</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">Format</span>\n          <span class=\"row-val\" id=\"teleFormat\">\u2014</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">Session Duration</span>\n          <span class=\"row-val\" id=\"teleSession\">00:00</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">Buffer Underruns</span>\n          <span class=\"row-val\" id=\"teleUnderruns\">0</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 2: WI-FI -->\n    <div class=\"tab-content\" id=\"tab-wifi\">\n      <div class=\"card\">\n        <div class=\"card-title\">Wi-Fi Connection</div>\n        <div class=\"row\">\n          <span class=\"row-label\">SSID</span>\n          <span class=\"row-val\" id=\"wifiSsid\">\u2014</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">IP Address</span>\n          <span class=\"row-val\" id=\"wifiIp\">\u2014</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">mDNS Hostname</span>\n          <span class=\"row-val\">http://c3music.local</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">Signal (RSSI)</span>\n          <span class=\"row-val\" id=\"wifiRssi\">\u2014</span>\n        </div>\n        <div style=\"margin-top: 16px;\">\n          <button onclick=\"postAction('/api/wifi/reconnect')\">Reconnect Wi-Fi</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 3: STREAMING SETUP -->\n    <div class=\"tab-content\" id=\"tab-stream\">\n      <div class=\"card\">\n        <div class=\"card-title\">Stream Configuration</div>\n        <div style=\"background: #16181f; border: 1px solid rgba(208, 188, 255, 0.2); border-radius: 20px; padding: 16px; margin-bottom: 16px;\">\n          <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\n            <span style=\"font-size: 11px; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.05em;\">Wi-Fi Auto-Discovery</span>\n            <span id=\"scanStatusBadge\" style=\"font-size: 11px; color: var(--text-muted);\">Subnet Scanner</span>\n          </div>\n          <p style=\"font-size: 12px; color: var(--text-muted); margin-bottom: 12px;\">Auto-detect audio transmitter on your home Wi-Fi instead of typing IP.</p>\n          <button type=\"button\" id=\"scanBtn\" onclick=\"discoverStreamers()\" style=\"width: 100%; height: 42px; font-size: 12px; font-weight: 600; background: rgba(208, 188, 255, 0.15); color: var(--primary); border: 1px solid rgba(208, 188, 255, 0.3);\">\n            \ud83d\udd0d Scan Home Wi-Fi for Streamers\n          </button>\n          <div id=\"discoveredBox\" style=\"display: none; margin-top: 12px; padding: 10px 12px; background: #0c0d10; border: 1px solid rgba(255,255,255,0.06); border-radius: 14px;\">\n            <div style=\"font-size: 11px; color: var(--text-muted); margin-bottom: 4px;\">Detected Stream Source:</div>\n            <div style=\"display: flex; justify-content: space-between; align-items: center;\">\n              <span id=\"discoveredHost\" style=\"font-family: monospace; font-size: 13px; color: var(--primary); font-weight: 600;\">\u2014</span>\n              <button type=\"button\" onclick=\"useDiscoveredHost()\" style=\"flex: 0 0 auto; height: 32px; padding: 0 14px; font-size: 11px; background: var(--primary); color: var(--on-primary); border: none;\">Use This</button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"field\">\n          <label>Android Phone IP / Host (or auto)</label>\n          <input type=\"text\" id=\"cfgHost\" placeholder=\"e.g. 192.168.1.50 or auto\">\n        </div>\n        <div class=\"field\">\n          <label>Preferred Protocol</label>\n          <select id=\"cfgMode\">\n            <option value=\"tcp\">Raw TCP (Port 50005 - Ultra Low Latency)</option>\n            <option value=\"http\">HTTP WAV (Port 8080 - Auto Format Detect)</option>\n          </select>\n        </div>\n        <div style=\"display: flex; gap: 12px;\">\n          <div class=\"field\" style=\"flex: 1;\">\n            <label>TCP Port</label>\n            <input type=\"number\" id=\"cfgTcpPort\" value=\"50005\">\n          </div>\n          <div class=\"field\" style=\"flex: 1;\">\n            <label>HTTP Port</label>\n            <input type=\"number\" id=\"cfgHttpPort\" value=\"8080\">\n          </div>\n        </div>\n\n        <div class=\"field\">\n          <div style=\"display: flex; justify-content: space-between;\">\n            <label>Buffer Target Latency</label>\n            <span id=\"bufMsLabel\" style=\"font-size: 12px; color: var(--primary);\">180 ms</span>\n          </div>\n          <input type=\"range\" id=\"cfgBufferMs\" min=\"80\" max=\"600\" step=\"10\" value=\"180\" oninput=\"document.getElementById('bufMsLabel').textContent = this.value + ' ms'\">\n        </div>\n\n        <div class=\"switch-row\">\n          <span style=\"font-size: 13px;\">Auto Protocol Fallback</span>\n          <input type=\"checkbox\" class=\"switch\" id=\"cfgFallback\">\n        </div>\n        <div class=\"switch-row\">\n          <span style=\"font-size: 13px;\">Auto Reconnect on Drop</span>\n          <input type=\"checkbox\" class=\"switch\" id=\"cfgAutoRecon\">\n        </div>\n\n        <div style=\"margin-top: 14px;\">\n          <button class=\"primary\" onclick=\"saveStreamSettings()\">Save & Reconnect</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 4: SETTINGS & OTA -->\n    <div class=\"tab-content\" id=\"tab-settings\">\n      <div class=\"card\">\n        <div class=\"card-title\">Display Settings</div>\n        <div class=\"switch-row\">\n          <div>\n            <div style=\"font-size: 14px; font-weight: 500;\">0.42\" OLED Screen</div>\n            <div style=\"font-size: 12px; color: var(--text-muted);\">Toggle screen on / off</div>\n          </div>\n          <input type=\"checkbox\" class=\"switch\" id=\"cfgOled\" onchange=\"toggleOled(this.checked)\">\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-title\">Firmware OTA Update</div>\n        <p style=\"font-size: 12px; color: var(--text-muted); margin-bottom: 12px;\">Select compiled .bin firmware binary from PlatformIO:</p>\n        <input type=\"file\" id=\"otaFile\" accept=\".bin\" style=\"margin-bottom: 10px; font-size: 12px;\">\n        <button id=\"otaBtn\" onclick=\"uploadOta()\">Install Firmware</button>\n        <div id=\"otaProgressBox\" style=\"display: none; margin-top: 10px;\">\n          <div class=\"buffer-track\">\n            <div class=\"buffer-fill\" id=\"otaProgressBar\" style=\"width: 0%;\"></div>\n          </div>\n          <div id=\"otaStatus\" style=\"font-size: 11px; color: var(--text-muted); margin-top: 4px;\">Uploading...</div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-title\">Hardware Pinout Reference</div>\n        <div class=\"row\">\n          <span class=\"row-label\">I2S BCLK</span>\n          <span class=\"row-val\">GPIO 3</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">I2S WSEL (LRCLK)</span>\n          <span class=\"row-val\">GPIO 1</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">I2S DOUT (DIN)</span>\n          <span class=\"row-val\">GPIO 10</span>\n        </div>\n        <div class=\"row\">\n          <span class=\"row-label\">OLED I2C (SDA / SCL)</span>\n          <span class=\"row-val\">GPIO 5 / GPIO 6</span>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-title\">Maintenance</div>\n        <div class=\"btn-group\">\n          <button onclick=\"postAction('/api/system/reboot')\">Reboot</button>\n          <button class=\"danger\" onclick=\"if(confirm('Factory reset?'))postAction('/api/system/factory-reset')\">Reset</button>\n        </div>\n      </div>\n    </div>\n  </main>\n\n  <!-- 4 Fixed App Navigation Tabs -->\n  <nav>\n    <button class=\"nav-btn active\" onclick=\"switchTab('now', this)\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M9 18V5l12-2v13\"></path><circle cx=\"6\" cy=\"18\" r=\"3\"></circle><circle cx=\"18\" cy=\"16\" r=\"3\"></circle></svg>\n      <span>Now Playing</span>\n    </button>\n    <button class=\"nav-btn\" onclick=\"switchTab('wifi', this)\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12.55a11 11 0 0 1 14.08 0\"></path><path d=\"M1.42 9a16 16 0 0 1 21.16 0\"></path><path d=\"M8.53 16.11a6 6 0 0 1 6.95 0\"></path><line x1=\"12\" y1=\"20\" x2=\"12.01\" y2=\"20\"></line></svg>\n      <span>Wi-Fi</span>\n    </button>\n    <button class=\"nav-btn\" onclick=\"switchTab('stream', this)\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M4 11a9 9 0 0 1 9 9\"></path><path d=\"M4 4a16 16 0 0 1 16 16\"></path><circle cx=\"5\" cy=\"19\" r=\"1\"></circle></svg>\n      <span>Streaming</span>\n    </button>\n    <button class=\"nav-btn\" onclick=\"switchTab('settings', this)\">\n      <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg>\n      <span>Settings</span>\n    </button>\n  </nav>\n\n  <div id=\"toast\"></div>\n\n  <script>\n    function showToast(msg) {\n      const t = document.getElementById('toast');\n      t.textContent = msg;\n      t.classList.add('show');\n      setTimeout(() => t.classList.remove('show'), 2400);\n    }\n\n    function switchTab(tabId, el) {\n      document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));\n      document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));\n      document.getElementById('tab-' + tabId).classList.add('active');\n      el.classList.add('active');\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    }\n\n    async function postAction(url) {\n      try {\n        const res = await fetch(url, { method: 'POST' });\n        const d = await res.json();\n        showToast(d.ok ? 'Action applied' : (d.error || 'Failed'));\n        setTimeout(pollStatus, 300);\n      } catch(e) {\n        showToast('Network error');\n      }\n    }\n\n    let discoveredTarget = null;\n    async function discoverStreamers() {\n      const btn = document.getElementById('scanBtn');\n      const badge = document.getElementById('scanStatusBadge');\n      btn.disabled = true;\n      btn.textContent = 'Scanning Subnet...';\n      badge.textContent = 'Probing...';\n      try {\n        const res = await fetch('/api/stream/discover');\n        const data = await res.json();\n        if (data.found && data.host) {\n          discoveredTarget = data;\n          document.getElementById('discoveredHost').textContent = data.host + (data.port === 50005 ? ' (TCP 50005)' : ' (HTTP 8080)');\n          document.getElementById('discoveredBox').style.display = 'block';\n          badge.textContent = 'Found!';\n          showToast('Found transmitter at ' + data.host);\n        } else {\n          showToast('No active stream found on subnet');\n          badge.textContent = 'Not found';\n        }\n      } catch(e) {\n        showToast('Scan request error');\n      }\n      btn.disabled = false;\n      btn.textContent = '\ud83d\udd0d Scan Home Wi-Fi for Streamers';\n    }\n\n    function useDiscoveredHost() {\n      if (discoveredTarget && discoveredTarget.host) {\n        document.getElementById('cfgHost').value = discoveredTarget.host;\n        if (discoveredTarget.port === 50005) document.getElementById('cfgMode').value = 'tcp';\n        else if (discoveredTarget.port === 8080) document.getElementById('cfgMode').value = 'http';\n        showToast('Applied ' + discoveredTarget.host);\n      }\n    }\n\n    let configLoaded = false;\n    async function loadConfig() {\n      try {\n        const r = await fetch('/api/config');\n        if (!r.ok) return;\n        const c = await r.json();\n        document.getElementById('cfgHost').value = c.host || '';\n        document.getElementById('cfgMode').value = c.mode || 'tcp';\n        document.getElementById('cfgTcpPort').value = c.tcpPort || 50005;\n        document.getElementById('cfgHttpPort').value = c.httpPort || 8080;\n        document.getElementById('cfgBufferMs').value = c.bufferMs || 180;\n        document.getElementById('bufMsLabel').textContent = (c.bufferMs || 180) + ' ms';\n        document.getElementById('cfgFallback').checked = !!c.autoFallback;\n        document.getElementById('cfgAutoRecon').checked = !!c.autoReconnect;\n        document.getElementById('cfgOled').checked = !!c.oled;\n        configLoaded = true;\n      } catch(e) {}\n    }\n\n    async function saveStreamSettings() {\n      const params = new URLSearchParams({\n        host: document.getElementById('cfgHost').value.trim(),\n        mode: document.getElementById('cfgMode').value,\n        tcpPort: document.getElementById('cfgTcpPort').value,\n        httpPort: document.getElementById('cfgHttpPort').value,\n        bufferMs: document.getElementById('cfgBufferMs').value,\n        autoFallback: document.getElementById('cfgFallback').checked ? '1' : '0',\n        autoReconnect: document.getElementById('cfgAutoRecon').checked ? '1' : '0'\n      });\n      try {\n        const r = await fetch('/api/config', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n          body: params\n        });\n        const d = await r.json();\n        showToast(d.ok ? 'Settings saved!' : 'Save failed');\n        setTimeout(pollStatus, 400);\n      } catch(e) {\n        showToast('Save failed');\n      }\n    }\n\n    async function toggleOled(enabled) {\n      const params = new URLSearchParams({ oled: enabled ? '1' : '0' });\n      await fetch('/api/config/oled', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n        body: params\n      });\n      showToast(enabled ? 'OLED turned ON' : 'OLED turned OFF');\n    }\n\n    function formatTime(sec) {\n      sec = Number(sec || 0);\n      const m = Math.floor(sec / 60);\n      const s = sec % 60;\n      return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');\n    }\n\n    async function pollStatus() {\n      try {\n        const res = await fetch('/api/status', { cache: 'no-store' });\n        if (!res.ok) throw 0;\n        const d = await res.json();\n\n        // Top Status Badge\n        const badge = document.getElementById('stateBadge');\n        document.getElementById('stateText').textContent = d.state || 'Ready';\n        badge.className = 'badge ' + (d.state === 'Streaming' ? 'ok' : d.state === 'Buffering' ? 'warn' : 'ok');\n\n        // Now Playing Hero\n        document.getElementById('heroStatus').textContent = d.state || 'Ready';\n        const meta = `${d.sampleRate || 44100} Hz \u00b7 ${d.channels === 2 ? 'Stereo' : 'Mono'} \u00b7 ${d.mode || 'TCP'}`;\n        document.getElementById('heroMeta').textContent = meta;\n\n        // Buffer Meter\n        const pct = Math.min(100, Math.max(0, d.bufferPercent || 0));\n        document.getElementById('bufBar').style.width = pct + '%';\n        document.getElementById('bufPercentText').textContent = pct + '%';\n\n        // Telemetry\n        document.getElementById('teleHost').textContent = (d.host || '\u2014') + ' (' + d.mode + ')';\n        document.getElementById('teleFormat').textContent = `${d.sampleRate} Hz \u00b7 16-bit`;\n        document.getElementById('teleSession').textContent = formatTime(d.sessionSeconds);\n        document.getElementById('teleUnderruns').textContent = d.underruns || 0;\n\n        // Wi-Fi tab\n        document.getElementById('wifiSsid').textContent = d.ssid || 'Disconnected';\n        document.getElementById('wifiIp').textContent = d.ip || '\u2014';\n        document.getElementById('wifiRssi').textContent = d.rssi ? d.rssi + ' dBm' : '\u2014';\n\n        if (!configLoaded) loadConfig();\n      } catch(e) {\n        document.getElementById('stateText').textContent = 'Offline';\n        document.getElementById('stateBadge').className = 'badge err';\n      }\n    }\n\n    function uploadOta() {\n      const file = document.getElementById('otaFile').files[0];\n      if (!file) {\n        showToast('Choose .bin file first');\n        return;\n      }\n      if (!confirm('Flash ' + file.name + ' over the air?')) return;\n\n      const fd = new FormData();\n      fd.append('firmware', file);\n\n      const box = document.getElementById('otaProgressBox');\n      const bar = document.getElementById('otaProgressBar');\n      const txt = document.getElementById('otaStatus');\n      const btn = document.getElementById('otaBtn');\n\n      box.style.display = 'block';\n      btn.disabled = true;\n\n      const xhr = new XMLHttpRequest();\n      xhr.upload.onprogress = e => {\n        if (e.lengthComputable) {\n          const p = Math.round((e.loaded / e.total) * 100);\n          bar.style.width = p + '%';\n          txt.textContent = 'Uploading: ' + p + '%';\n        }\n      };\n      xhr.onload = () => {\n        btn.disabled = false;\n        if (xhr.status === 200) {\n          bar.style.width = '100%';\n          txt.textContent = 'Success! Device is rebooting...';\n          showToast('OTA Finished! Rebooting');\n        } else {\n          txt.textContent = 'OTA Failed: ' + xhr.responseText;\n        }\n      };\n      xhr.open('POST', '/api/ota');\n      xhr.send(fd);\n    }\n\n    setInterval(pollStatus, 1000);\n    pollStatus();\n  </script>\n</body>\n</html>\n)rawliteral\";\n",
  "include/web_server.h": "#pragma once\n\n#include \"config.h\"\n#include <WebServer.h>\n\nclass WebServerManager {\npublic:\n  static WebServerManager& instance();\n\n  void begin();\n  void handleClient();\n  void beginMdnsIfNeeded();\n\nprivate:\n  WebServerManager();\n\n  WebServer _server;\n  bool _mdnsStarted;\n  bool _otaFailed;\n  String _otaError;\n\n  void setupRoutes();\n  void handleFirmwareUpload();\n  void sendJsonResponse(int code, const String& json);\n};\n",
  "include/stream_client.h": "#pragma once\n\n#include \"config.h\"\n#include <WiFiClient.h>\n\nclass StreamClient {\npublic:\n  static StreamClient& instance();\n\n  void begin();\n  bool connect(uint16_t port);\n  void stop();\n  bool isConnected();\n\n  // Primary stream loop: reads from socket into AudioRingBuffer\n  void processStream();\n\n  StreamFormat currentFormat() const { return _format; }\n  void setFormat(const StreamFormat& f) { _format = f; }\n\n  bool connectTcp(const String& host, uint16_t port);\n  bool connectHttp(const String& host, uint16_t port);\n  bool autoDiscoverHost(String& foundHost, uint16_t& foundPort);\n\nprivate:\n  StreamClient();\n  WiFiClient _client;\n  StreamFormat _format;\n  uint8_t _networkBuffer[NETWORK_READ_CHUNK];\n  uint32_t _lastRxMs;\n\n  bool readExact(uint8_t* buf, size_t len, uint32_t timeoutMs);\n  bool readLine(String& line, uint32_t timeoutMs);\n  bool parseHttpHeaders();\n  bool parseWavHeader(StreamFormat& outFormat);\n};\n",
  "src/audio_i2s.cpp": "#include \"audio_i2s.h\"\n#include <math.h>\n\nAudioI2S& AudioI2S::instance() {\n  static AudioI2S inst;\n  return inst;\n}\n\nAudioI2S::AudioI2S() : _ready(false) {\n  _mutex = xSemaphoreCreateMutex();\n}\n\nAudioI2S::~AudioI2S() {\n  end();\n  if (_mutex) {\n    vSemaphoreDelete(_mutex);\n  }\n}\n\nvoid AudioI2S::end() {\n  if (_mutex) xSemaphoreTake(_mutex, portMAX_DELAY);\n  if (_ready) {\n    i2s_driver_uninstall(I2S_NUM_0);\n    _ready = false;\n  }\n  if (_mutex) xSemaphoreGive(_mutex);\n}\n\nbool AudioI2S::begin(uint32_t sampleRate, uint16_t channels, uint16_t bitsPerSample) {\n  if (bitsPerSample != 16 || (channels != 1 && channels != 2)) {\n    return false;\n  }\n\n  end();\n\n  if (_mutex) xSemaphoreTake(_mutex, portMAX_DELAY);\n\n  // ESP32-C3 Hardware I2S Configuration for UDA1334A\n  i2s_config_t i2s_config = {\n    .mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),\n    .sample_rate = sampleRate,\n    .bits_per_sample = I2S_BITS_PER_SAMPLE_16BIT,\n    .channel_format = I2S_CHANNEL_FMT_RIGHT_LEFT, // Always stream stereo to UDA1334A\n    .communication_format = I2S_COMM_FORMAT_STAND_I2S,\n    .intr_alloc_flags = ESP_INTR_FLAG_LEVEL1,\n    .dma_buf_count = 8,\n    .dma_buf_len = 512,\n    .use_apll = false,          // ESP32-C3 does NOT support APLL!\n    .tx_desc_auto_clear = true,  // Automatically mute on underrun\n    .fixed_mclk = 0             // Must be 0 for internal clock divisor calculation!\n  };\n\n  esp_err_t err = i2s_driver_install(I2S_NUM_0, &i2s_config, 0, nullptr);\n  if (err != ESP_OK) {\n    Serial.printf(\"[I2S] Driver install failed: 0x%x\\n\", err);\n    if (_mutex) xSemaphoreGive(_mutex);\n    return false;\n  }\n\n  i2s_pin_config_t pin_config = {\n    .bck_io_num = PIN_I2S_BCLK,\n    .ws_io_num = PIN_I2S_LRCLK,\n    .data_out_num = PIN_I2S_DOUT,\n    .data_in_num = I2S_PIN_NO_CHANGE\n  };\n\n  err = i2s_set_pin(I2S_NUM_0, &pin_config);\n  if (err != ESP_OK) {\n    Serial.printf(\"[I2S] Pin configuration failed: 0x%x\\n\", err);\n    i2s_driver_uninstall(I2S_NUM_0);\n    if (_mutex) xSemaphoreGive(_mutex);\n    return false;\n  }\n\n  i2s_zero_dma_buffer(I2S_NUM_0);\n  _ready = true;\n  if (_mutex) xSemaphoreGive(_mutex);\n\n  Serial.printf(\"[I2S] Initialized: %u Hz, 16-bit, %s (BCLK=%d, WS=%d, DOUT=%d)\\n\",\n                sampleRate, channels == 2 ? \"Stereo\" : \"Mono\",\n                PIN_I2S_BCLK, PIN_I2S_LRCLK, PIN_I2S_DOUT);\n  return true;\n}\n\nvoid AudioI2S::clearDmaBuffer() {\n  if (_mutex) xSemaphoreTake(_mutex, portMAX_DELAY);\n  if (_ready) {\n    i2s_zero_dma_buffer(I2S_NUM_0);\n  }\n  if (_mutex) xSemaphoreGive(_mutex);\n}\n\nvoid AudioI2S::playTestTone(uint32_t durationMs) {\n  if (!_ready) {\n    begin(DEFAULT_SAMPLE_RATE, DEFAULT_CHANNELS);\n  }\n  const int totalSamples = (DEFAULT_SAMPLE_RATE * durationMs) / 1000;\n  int16_t sampleBuf[128 * 2];\n  size_t bytesWritten = 0;\n\n  for (int i = 0; i < totalSamples; i += 128) {\n    for (int s = 0; s < 128; s++) {\n      float t = (float)(i + s) / (float)DEFAULT_SAMPLE_RATE;\n      int16_t val = (int16_t)(sin(2.0 * M_PI * 440.0 * t) * 12000.0);\n      sampleBuf[s * 2]     = val; // L\n      sampleBuf[s * 2 + 1] = val; // R\n    }\n    writeSamples((uint8_t*)sampleBuf, sizeof(sampleBuf), 100);\n  }\n  clearDmaBuffer();\n}\n\nsize_t AudioI2S::writeSamples(const uint8_t* data, size_t length, uint32_t timeoutTicks) {\n  if (!data || length == 0 || !_ready) return 0;\n\n  size_t bytesWritten = 0;\n  if (_mutex) xSemaphoreTake(_mutex, portMAX_DELAY);\n  if (_ready) {\n    i2s_write(I2S_NUM_0, data, length, &bytesWritten, pdMS_TO_TICKS(timeoutTicks));\n  }\n  if (_mutex) xSemaphoreGive(_mutex);\n  return bytesWritten;\n}\n\nsize_t AudioI2S::writeMonoAsStereo(const uint8_t* monoData, size_t length, uint32_t timeoutTicks) {\n  if (!monoData || length == 0 || !_ready) return 0;\n\n  size_t numSamples = length / 2;\n  size_t maxSamplesPerChunk = sizeof(_stereoExpandBuffer) / 4;\n  size_t totalWritten = 0;\n\n  const int16_t* inSamples = reinterpret_cast<const int16_t*>(monoData);\n  int16_t* outSamples = reinterpret_cast<int16_t*>(_stereoExpandBuffer);\n\n  for (size_t offset = 0; offset < numSamples; offset += maxSamplesPerChunk) {\n    size_t chunkSamples = min(numSamples - offset, maxSamplesPerChunk);\n    for (size_t i = 0; i < chunkSamples; i++) {\n      int16_t sample = inSamples[offset + i];\n      outSamples[i * 2]     = sample;\n      outSamples[i * 2 + 1] = sample;\n    }\n    size_t bytesToWrite = chunkSamples * 4;\n    size_t written = writeSamples(_stereoExpandBuffer, bytesToWrite, timeoutTicks);\n    totalWritten += (written / 2);\n  }\n\n  return totalWritten;\n}\n",
  "src/audio_ringbuf.cpp": "#include \"audio_ringbuf.h\"\n#include <string.h>\n\nAudioRingBuffer& AudioRingBuffer::instance() {\n  static AudioRingBuffer inst;\n  return inst;\n}\n\nAudioRingBuffer::AudioRingBuffer()\n  : _readIndex(0), _writeIndex(0), _count(0) {\n  _mux = portMUX_INITIALIZER_UNLOCKED;\n  _dataSemaphore = xSemaphoreCreateBinary();\n}\n\nAudioRingBuffer::~AudioRingBuffer() {\n  if (_dataSemaphore) {\n    vSemaphoreDelete(_dataSemaphore);\n  }\n}\n\nbool AudioRingBuffer::write(const uint8_t* data, size_t length) {\n  if (!data || length == 0) return true;\n\n  bool ok = true;\n  portENTER_CRITICAL(&_mux);\n  size_t freeBytes = AUDIO_RING_BYTES - _count;\n  if (length > freeBytes) {\n    length = freeBytes;\n    ok = false;\n  }\n\n  size_t first = min(length, (size_t)(AUDIO_RING_BYTES - _writeIndex));\n  memcpy(_buffer + _writeIndex, data, first);\n  size_t second = length - first;\n  if (second > 0) {\n    memcpy(_buffer, data + first, second);\n  }\n\n  _writeIndex = (_writeIndex + length) % AUDIO_RING_BYTES;\n  _count += length;\n  portEXIT_CRITICAL(&_mux);\n\n  if (length > 0 && _dataSemaphore) {\n    xSemaphoreGive(_dataSemaphore);\n  }\n  return ok;\n}\n\nsize_t AudioRingBuffer::read(uint8_t* destination, size_t maxLen) {\n  if (!destination || maxLen == 0) return 0;\n\n  portENTER_CRITICAL(&_mux);\n  size_t availableCount = _count;\n  size_t len = min(maxLen, availableCount);\n  if (len > 0) {\n    size_t first = min(len, (size_t)(AUDIO_RING_BYTES - _readIndex));\n    memcpy(destination, _buffer + _readIndex, first);\n    size_t second = len - first;\n    if (second > 0) {\n      memcpy(destination + first, _buffer, second);\n    }\n    _readIndex = (_readIndex + len) % AUDIO_RING_BYTES;\n    _count -= len;\n  }\n  portEXIT_CRITICAL(&_mux);\n  return len;\n}\n\nvoid AudioRingBuffer::clear() {\n  portENTER_CRITICAL(&_mux);\n  _readIndex = 0;\n  _writeIndex = 0;\n  _count = 0;\n  portEXIT_CRITICAL(&_mux);\n}\n\nsize_t AudioRingBuffer::available() const {\n  portENTER_CRITICAL((portMUX_TYPE*)&_mux);\n  size_t val = _count;\n  portEXIT_CRITICAL((portMUX_TYPE*)&_mux);\n  return val;\n}\n\nsize_t AudioRingBuffer::freeSpace() const {\n  return AUDIO_RING_BYTES - available();\n}\n\nuint8_t AudioRingBuffer::percentFull() const {\n  return (uint8_t)((available() * 100UL) / AUDIO_RING_BYTES);\n}\n",
  "src/display_oled.cpp": "#include \"display_oled.h\"\n#include <Wire.h>\n#include <WiFi.h>\n\nDisplayOLED& DisplayOLED::instance() {\n  static DisplayOLED inst;\n  return inst;\n}\n\nDisplayOLED::DisplayOLED()\n  : _u8g2(U8G2_R0, U8X8_PIN_NONE), _available(false), _enabled(true), _vuLevel(0), _lastRenderMs(0) {\n}\n\nvoid DisplayOLED::begin() {\n  Wire.begin(PIN_I2C_SDA, PIN_I2C_SCL);\n  _available = _u8g2.begin();\n  if (_available) {\n    _u8g2.setPowerSave(_enabled ? 0 : 1);\n    _u8g2.clearBuffer();\n    _u8g2.setFont(u8g2_font_5x7_tf);\n    _u8g2.drawStr(0, 8, \"C3 MUSIC\");\n    _u8g2.drawStr(0, 20, \"Material v2\");\n    _u8g2.sendBuffer();\n  }\n}\n\nvoid DisplayOLED::setEnabled(bool enabled) {\n  _enabled = enabled;\n  if (_available) {\n    _u8g2.setPowerSave(_enabled ? 0 : 1);\n  }\n}\n\nvoid DisplayOLED::drawCentered(const char* text, uint8_t y, const uint8_t* font) {\n  _u8g2.setFont(font);\n  int w = _u8g2.getStrWidth(text);\n  int x = (OLED_WIDTH - w) / 2;\n  if (x < 0) x = 0;\n  _u8g2.drawStr(x, y, text);\n}\n\nvoid DisplayOLED::update(ReceiverState state, const StreamFormat& format, uint8_t bufferPercent, const String& error) {\n  if (!_available || !_enabled) return;\n\n  // Frame limiter: ~15-20 FPS max (every 60ms) to conserve CPU\n  if (millis() - _lastRenderMs < 60) return;\n  _lastRenderMs = millis();\n\n  _u8g2.clearBuffer();\n  _u8g2.setFont(u8g2_font_5x7_tf);\n  _u8g2.drawStr(0, 7, \"C3 MUSIC\");\n\n  // State badge in top right\n  const char* st = \"BOOT\";\n  switch(state) {\n    case RX_WIFI_CONNECTING: st = \"WIFI\"; break;\n    case RX_WIFI_OFFLINE:    st = \"OFFLINE\"; break;\n    case RX_IDLE:            st = \"READY\"; break;\n    case RX_CONNECTING:      st = \"LINK\"; break;\n    case RX_BUFFERING:       st = \"BUF\"; break;\n    case RX_STREAMING:       st = \"PLAY\"; break;\n    case RX_STOPPED:         st = \"STOP\"; break;\n    case RX_ERROR:           st = \"ERR\"; break;\n    case RX_UPDATING:        st = \"OTA\"; break;\n    default: break;\n  }\n  int sw = _u8g2.getStrWidth(st);\n  _u8g2.drawStr(OLED_WIDTH - sw, 7, st);\n\n  if (state == RX_STREAMING || state == RX_BUFFERING) {\n    // Format: e.g. \"44k ST\" or \"48k MO\"\n    char fmtBuf[20];\n    snprintf(fmtBuf, sizeof(fmtBuf), \"%uk %s\", (unsigned int)(format.sampleRate / 1000), format.channels == 2 ? \"ST\" : \"MO\");\n    drawCentered(fmtBuf, 18, u8g2_font_6x10_tf);\n\n    // Dynamic mini VU meter & Buffer Bar\n    _u8g2.drawFrame(0, 24, OLED_WIDTH, 6);\n    uint8_t barW = (uint8_t)(((OLED_WIDTH - 2) * bufferPercent) / 100);\n    if (barW > 0) {\n      _u8g2.drawBox(1, 25, barW, 4);\n    }\n\n    // Mini 7-bar VU visualizer on bottom\n    for (int i = 0; i < 7; i++) {\n      int barH = (_vuLevel > (i * 4)) ? (i + 1) : 1;\n      _u8g2.drawBox(i * 10 + 2, 40 - barH, 6, barH);\n    }\n  } else {\n    // Info display when not playing\n    if (WiFi.status() == WL_CONNECTED) {\n      String ip = WiFi.localIP().toString();\n      drawCentered(ip.c_str(), 21, u8g2_font_5x7_tf);\n    } else if (state == RX_WIFI_CONNECTING) {\n      drawCentered(\"Connecting...\", 21, u8g2_font_5x7_tf);\n    } else {\n      drawCentered(\"Check WiFi\", 21, u8g2_font_5x7_tf);\n    }\n\n    if (state == RX_ERROR && error.length() > 0) {\n      String e = error;\n      if (e.length() > 14) e = e.substring(0, 14);\n      drawCentered(e.c_str(), 36, u8g2_font_4x6_tf);\n    } else {\n      drawCentered(\"c3music.local\", 36, u8g2_font_4x6_tf);\n    }\n  }\n\n  _u8g2.sendBuffer();\n}\n",
  "src/stream_client.cpp": "#include \"stream_client.h\"\n#include \"audio_ringbuf.h\"\n#include \"audio_i2s.h\"\n#include <WiFi.h>\n\nextern AppSettings g_settings;\nextern RuntimeStats g_stats;\nextern volatile ReceiverState g_receiverState;\nextern volatile bool g_bufferStarted;\n\nStreamClient& StreamClient::instance() {\n  static StreamClient inst;\n  return inst;\n}\n\nStreamClient::StreamClient() : _lastRxMs(0) {\n}\n\nvoid StreamClient::begin() {\n  _client.setTimeout(3); // 3 seconds timeout\n}\n\nvoid StreamClient::stop() {\n  _client.stop();\n}\n\nbool StreamClient::isConnected() {\n  return _client.connected();\n}\n\nbool StreamClient::readExact(uint8_t* buf, size_t len, uint32_t timeoutMs) {\n  size_t got = 0;\n  uint32_t start = millis();\n  while (got < len) {\n    int av = _client.available();\n    if (av > 0) {\n      size_t toRead = min((size_t)av, (size_t)(len - got));\n      int n = _client.read(buf + got, toRead);\n      if (n > 0) {\n        got += n;\n        start = millis();\n      }\n    } else {\n      if (!_client.connected() || (millis() - start > timeoutMs)) {\n        return false;\n      }\n      delay(1);\n    }\n  }\n  return got == len;\n}\n\nbool StreamClient::readLine(String& line, uint32_t timeoutMs) {\n  line = \"\";\n  uint32_t start = millis();\n  while (_client.connected() && (millis() - start < timeoutMs)) {\n    if (_client.available()) {\n      char c = (char)_client.read();\n      line += c;\n      if (line.endsWith(\"\\r\\n\")) {\n        return true;\n      }\n      start = millis();\n    } else {\n      delay(1);\n    }\n  }\n  return false;\n}\n\nbool StreamClient::parseHttpHeaders() {\n  String statusLine;\n  if (!readLine(statusLine, 5000)) return false;\n  statusLine.trim();\n  if (!statusLine.startsWith(\"HTTP/\") || statusLine.indexOf(\"200\") < 0) {\n    return false;\n  }\n  g_stats.lastHttpStatus = 200;\n\n  String header;\n  while (readLine(header, 5000)) {\n    if (header == \"\\r\\n\" || header.length() == 0) return true;\n  }\n  return false;\n}\n\nbool StreamClient::parseWavHeader(StreamFormat& outFormat) {\n  uint8_t riff[12];\n  if (!readExact(riff, 12, 5000)) return false;\n  if (memcmp(riff, \"RIFF\", 4) != 0 || memcmp(riff + 8, \"WAVE\", 4) != 0) {\n    return false;\n  }\n\n  bool fmtFound = false;\n  while (_client.connected()) {\n    uint8_t chunkHeader[8];\n    if (!readExact(chunkHeader, 8, 4000)) break;\n\n    uint32_t chunkSize = (uint32_t)chunkHeader[4] | ((uint32_t)chunkHeader[5] << 8) |\n                         ((uint32_t)chunkHeader[6] << 16) | ((uint32_t)chunkHeader[7] << 24);\n\n    if (memcmp(chunkHeader, \"fmt \", 4) == 0) {\n      if (chunkSize < 16 || chunkSize > 64) return false;\n      uint8_t fmtBuf[64];\n      if (!readExact(fmtBuf, chunkSize, 4000)) return false;\n\n      outFormat.audioFormat = fmtBuf[0] | (fmtBuf[1] << 8);\n      outFormat.channels = fmtBuf[2] | (fmtBuf[3] << 8);\n      outFormat.sampleRate = (uint32_t)fmtBuf[4] | ((uint32_t)fmtBuf[5] << 8) |\n                             ((uint32_t)fmtBuf[6] << 16) | ((uint32_t)fmtBuf[7] << 24);\n      outFormat.bitsPerSample = fmtBuf[14] | (fmtBuf[15] << 8);\n      outFormat.valid = (outFormat.audioFormat == 1 && outFormat.bitsPerSample == 16);\n      fmtFound = true;\n    } else if (memcmp(chunkHeader, \"data\", 4) == 0) {\n      return fmtFound;\n    } else {\n      // Skip unknown chunk\n      uint8_t discard[64];\n      uint32_t rem = chunkSize;\n      while (rem > 0) {\n        size_t toRead = min((size_t)sizeof(discard), (size_t)rem);\n        if (!readExact(discard, toRead, 3000)) return false;\n        rem -= toRead;\n      }\n      if (chunkSize & 1) _client.read(); // Pad byte\n    }\n  }\n  return false;\n}\n\nbool StreamClient::connectTcp(const String& host, uint16_t port) {\n  _client.stop();\n  Serial.printf(\"[STREAM] Connecting to Raw TCP %s:%u...\\n\", host.c_str(), port);\n\n  if (!_client.connect(host.c_str(), port)) {\n    return false;\n  }\n  _client.setNoDelay(true);\n\n  // Default raw PCM settings\n  _format.sampleRate = DEFAULT_SAMPLE_RATE;\n  _format.channels = DEFAULT_CHANNELS;\n  _format.bitsPerSample = DEFAULT_BITS_PER_SAMPLE;\n  _format.valid = true;\n\n  AudioI2S::instance().begin(_format.sampleRate, _format.channels);\n  return true;\n}\n\nbool StreamClient::connectHttp(const String& host, uint16_t port) {\n  _client.stop();\n  Serial.printf(\"[STREAM] Connecting to HTTP WAV http://%s:%u/ ...\\n\", host.c_str(), port);\n\n  if (!_client.connect(host.c_str(), port)) {\n    return false;\n  }\n  _client.setNoDelay(true);\n\n  // Request root path for pkarthikmohan/wifi-audio-streamer\n  _client.printf(\"GET / HTTP/1.1\\r\\nHost: %s:%u\\r\\nUser-Agent: C3Music/2.0\\r\\nAccept: audio/wav,*/*\\r\\nConnection: close\\r\\n\\r\\n\",\n                 host.c_str(), port);\n\n  if (!parseHttpHeaders()) {\n    _client.stop();\n    return false;\n  }\n\n  StreamFormat wavFormat;\n  if (!parseWavHeader(wavFormat) || !wavFormat.valid) {\n    _client.stop();\n    return false;\n  }\n\n  _format = wavFormat;\n  Serial.printf(\"[STREAM] Auto-detected WAV format: %u Hz, %s\\n\", _format.sampleRate, _format.channels == 2 ? \"Stereo\" : \"Mono\");\n  AudioI2S::instance().begin(_format.sampleRate, _format.channels);\n  return true;\n}\n\nvoid StreamClient::processStream() {\n  int availableBytes = _client.available();\n  if (availableBytes > 0) {\n    size_t toRead = min((size_t)availableBytes, (size_t)sizeof(_networkBuffer));\n    int bytesRead = _client.read(_networkBuffer, toRead);\n\n    if (bytesRead > 0) {\n      g_stats.bytesReceived += bytesRead;\n      _lastRxMs = millis();\n\n      AudioRingBuffer::instance().write(_networkBuffer, bytesRead);\n\n      // Pre-buffering threshold to start playback without stutter (~12KB)\n      if (!g_bufferStarted && AudioRingBuffer::instance().available() >= 12000) {\n        g_bufferStarted = true;\n        g_receiverState = RX_STREAMING;\n      }\n    }\n  } else {\n    vTaskDelay(pdMS_TO_TICKS(1));\n  }\n}\n\nbool StreamClient::autoDiscoverHost(String& foundHost, uint16_t& foundPort) {\n  if (WiFi.status() != WL_CONNECTED) return false;\n\n  Serial.println(\"[DISCOVERY] Scanning home Wi-Fi subnet for active audio transmitters...\");\n\n  // 1. First probe configured host if valid\n  if (g_settings.phoneHost.length() > 0 && g_settings.phoneHost != \"auto\") {\n    WiFiClient probe;\n    probe.setTimeout(1);\n    if (probe.connect(g_settings.phoneHost.c_str(), g_settings.tcpPort)) {\n      probe.stop();\n      foundHost = g_settings.phoneHost;\n      foundPort = g_settings.tcpPort;\n      return true;\n    }\n    if (probe.connect(g_settings.phoneHost.c_str(), g_settings.httpPort)) {\n      probe.stop();\n      foundHost = g_settings.phoneHost;\n      foundPort = g_settings.httpPort;\n      return true;\n    }\n  }\n\n  // 2. Scan local subnet based on ESP32 IP\n  IPAddress localIp = WiFi.localIP();\n  IPAddress gateway = WiFi.gatewayIP();\n  IPAddress target = localIp;\n\n  // Scan nearest 40 host IPs around local IP and gateway\n  int myLastOctet = localIp[3];\n  int probeRange[] = { 119, 100, 101, 102, 105, 110, 115, 120, 150, 200, 50, 2, 3 };\n\n  for (int octet : probeRange) {\n    target[3] = octet;\n    if (target == localIp) continue;\n\n    WiFiClient probe;\n    probe.setTimeout(1); // 1 second maximum socket connection probe\n\n    // Test Port 50005 (TCP PCM)\n    if (probe.connect(target, 50005)) {\n      probe.stop();\n      foundHost = target.toString();\n      foundPort = 50005;\n      Serial.printf(\"[DISCOVERY] Found active TCP PCM Streamer at %s:50005\\n\", foundHost.c_str());\n      return true;\n    }\n\n    // Test Port 8080 (HTTP WAV)\n    if (probe.connect(target, 8080)) {\n      probe.stop();\n      foundHost = target.toString();\n      foundPort = 8080;\n      Serial.printf(\"[DISCOVERY] Found active HTTP WAV Streamer at %s:8080\\n\", foundHost.c_str());\n      return true;\n    }\n  }\n\n  Serial.println(\"[DISCOVERY] No active transmitter detected. Ready for manual entry.\");\n  return false;\n}\n",
  "src/web_server.cpp": "#include \"web_server.h\"\n#include \"web_assets.h\"\n#include \"audio_ringbuf.h\"\n#include \"display_oled.h\"\n#include \"stream_client.h\"\n#include <WiFi.h>\n#include <ESPmDNS.h>\n#include <Update.h>\n#include <Preferences.h>\n\nextern AppSettings g_settings;\nextern RuntimeStats g_stats;\nextern volatile ReceiverState g_receiverState;\nextern Preferences g_preferences;\nextern void savePreferences();\nextern void restartStreaming();\n\nWebServerManager& WebServerManager::instance() {\n  static WebServerManager inst;\n  return inst;\n}\n\nWebServerManager::WebServerManager()\n  : _server(80), _mdnsStarted(false), _otaFailed(false) {\n}\n\nvoid WebServerManager::begin() {\n  setupRoutes();\n  _server.begin();\n  Serial.println(\"[WEB] Material AMOLED Web Server started on port 80\");\n}\n\nvoid WebServerManager::handleClient() {\n  _server.handleClient();\n}\n\nvoid WebServerManager::beginMdnsIfNeeded() {\n  if (_mdnsStarted || WiFi.status() != WL_CONNECTED) return;\n  if (MDNS.begin(MDNS_HOSTNAME)) {\n    MDNS.addService(\"http\", \"tcp\", 80);\n    _mdnsStarted = true;\n    Serial.printf(\"[MDNS] http://%s.local/\\n\", MDNS_HOSTNAME);\n  }\n}\n\nvoid WebServerManager::sendJsonResponse(int code, const String& json) {\n  _server.sendHeader(\"Cache-Control\", \"no-store, no-cache, must-revalidate\");\n  _server.send(code, \"application/json\", json);\n}\n\nvoid WebServerManager::handleFirmwareUpload() {\n  HTTPUpload& up = _server.upload();\n  if (up.status == UPLOAD_FILE_START) {\n    _otaFailed = false;\n    _otaError = \"\";\n    g_receiverState = RX_UPDATING;\n    StreamClient::instance().stop();\n    AudioRingBuffer::instance().clear();\n\n    if (!Update.begin(UPDATE_SIZE_UNKNOWN, U_FLASH)) {\n      _otaFailed = true;\n      _otaError = Update.errorString();\n    }\n  } else if (up.status == UPLOAD_FILE_WRITE) {\n    if (!_otaFailed && Update.write(up.buf, up.currentSize) != up.currentSize) {\n      _otaFailed = true;\n      _otaError = Update.errorString();\n    }\n  } else if (up.status == UPLOAD_FILE_END) {\n    if (!_otaFailed && !Update.end(true)) {\n      _otaFailed = true;\n      _otaError = Update.errorString();\n    }\n  } else if (up.status == UPLOAD_FILE_ABORTED) {\n    _otaFailed = true;\n    _otaError = \"Upload aborted\";\n    Update.abort();\n  }\n}\n\nvoid WebServerManager::setupRoutes() {\n  // Main Web App (HTML_INDEX from web_assets.h)\n  _server.on(\"/\", HTTP_GET, [this]() {\n    _server.sendHeader(\"Cache-Control\", \"no-store, no-cache\");\n    _server.send_P(200, \"text/html\", HTML_INDEX);\n  });\n\n  // Telemetry JSON\n  _server.on(\"/api/status\", HTTP_GET, [this]() {\n    uint32_t sessionSec = (g_stats.sessionStartedMs > 0 && g_receiverState == RX_STREAMING)\n      ? (millis() - g_stats.sessionStartedMs) / 1000\n      : 0;\n\n    String json = \"{\";\n    json += \"\\\"device\\\":\\\"\" + String(DEVICE_NAME) + \"\\\",\";\n    json += \"\\\"version\\\":\\\"\" + String(FIRMWARE_VERSION) + \"\\\",\";\n    json += \"\\\"state\\\":\\\"\" + String(g_receiverState == RX_STREAMING ? \"Streaming\" : g_receiverState == RX_BUFFERING ? \"Buffering\" : \"Ready\") + \"\\\",\";\n    json += \"\\\"host\\\":\\\"\" + g_settings.phoneHost + \"\\\",\";\n    json += \"\\\"mode\\\":\\\"\" + String(g_settings.preferredMode == STREAM_MODE_HTTP ? \"HTTP WAV\" : \"Raw TCP\") + \"\\\",\";\n    json += \"\\\"sampleRate\\\":\" + String(StreamClient::instance().currentFormat().sampleRate) + \",\";\n    json += \"\\\"channels\\\":\" + String(StreamClient::instance().currentFormat().channels) + \",\";\n    json += \"\\\"bufferPercent\\\":\" + String(AudioRingBuffer::instance().percentFull()) + \",\";\n    json += \"\\\"underruns\\\":\" + String(g_stats.underruns) + \",\";\n    json += \"\\\"sessionSeconds\\\":\" + String(sessionSec) + \",\";\n    json += \"\\\"bytesReceived\\\":\" + String(g_stats.bytesReceived) + \",\";\n    json += \"\\\"ssid\\\":\\\"\" + String(WiFi.SSID()) + \"\\\",\";\n    json += \"\\\"ip\\\":\\\"\" + WiFi.localIP().toString() + \"\\\",\";\n    json += \"\\\"rssi\\\":\" + String(WiFi.RSSI()) + \",\";\n    json += \"\\\"oled\\\":\" + String(g_settings.oledEnabled ? \"true\" : \"false\");\n    json += \"}\";\n    sendJsonResponse(200, json);\n  });\n\n  // Config JSON GET\n  _server.on(\"/api/config\", HTTP_GET, [this]() {\n    String json = \"{\";\n    json += \"\\\"host\\\":\\\"\" + g_settings.phoneHost + \"\\\",\";\n    json += \"\\\"tcpPort\\\":\" + String(g_settings.tcpPort) + \",\";\n    json += \"\\\"httpPort\\\":\" + String(g_settings.httpPort) + \",\";\n    json += \"\\\"mode\\\":\\\"\" + String(g_settings.preferredMode == STREAM_MODE_HTTP ? \"http\" : \"tcp\") + \"\\\",\";\n    json += \"\\\"bufferMs\\\":\" + String(g_settings.targetBufferMs) + \",\";\n    json += \"\\\"autoFallback\\\":\" + String(g_settings.autoFallback ? \"true\" : \"false\") + \",\";\n    json += \"\\\"autoReconnect\\\":\" + String(g_settings.autoReconnect ? \"true\" : \"false\") + \",\";\n    json += \"\\\"oled\\\":\" + String(g_settings.oledEnabled ? \"true\" : \"false\");\n    json += \"}\";\n    sendJsonResponse(200, json);\n  });\n\n  // Config POST\n  _server.on(\"/api/config\", HTTP_POST, [this]() {\n    if (_server.hasArg(\"host\")) g_settings.phoneHost = _server.arg(\"host\");\n    if (_server.hasArg(\"tcpPort\")) g_settings.tcpPort = _server.arg(\"tcpPort\").toInt();\n    if (_server.hasArg(\"httpPort\")) g_settings.httpPort = _server.arg(\"httpPort\").toInt();\n    if (_server.hasArg(\"bufferMs\")) g_settings.targetBufferMs = _server.arg(\"bufferMs\").toInt();\n    if (_server.hasArg(\"mode\")) g_settings.preferredMode = (_server.arg(\"mode\") == \"http\") ? STREAM_MODE_HTTP : STREAM_MODE_TCP;\n    if (_server.hasArg(\"autoFallback\")) g_settings.autoFallback = (_server.arg(\"autoFallback\") == \"1\");\n    if (_server.hasArg(\"autoReconnect\")) g_settings.autoReconnect = (_server.arg(\"autoReconnect\") == \"1\");\n\n    savePreferences();\n    restartStreaming();\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  // OLED Toggle\n  _server.on(\"/api/config/oled\", HTTP_POST, [this]() {\n    if (_server.hasArg(\"oled\")) {\n      g_settings.oledEnabled = (_server.arg(\"oled\") == \"1\");\n      DisplayOLED::instance().setEnabled(g_settings.oledEnabled);\n      savePreferences();\n    }\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  // Playback Controls\n  _server.on(\"/api/stream/discover\", HTTP_GET, [this]() {\n    String foundHost = \"\";\n    uint16_t foundPort = 0;\n    bool ok = StreamClient::instance().autoDiscoverHost(foundHost, foundPort);\n    if (ok) {\n      g_settings.phoneHost = foundHost;\n      if (foundPort == 50005) g_settings.preferredMode = STREAM_MODE_TCP;\n      else if (foundPort == 8080) g_settings.preferredMode = STREAM_MODE_HTTP;\n      savePreferences();\n      String res = \"{\\\"ok\\\":true,\\\"found\\\":true,\\\"host\\\":\\\"\" + foundHost + \"\\\",\\\"port\\\":\" + String(foundPort) + \"}\";\n      sendJsonResponse(200, res);\n    } else {\n      sendJsonResponse(200, \"{\\\"ok\\\":true,\\\"found\\\":false,\\\"message\\\":\\\"No active streamer found on subnet\\\"}\");\n    }\n  });\n\n  _server.on(\"/api/stream/start\", HTTP_POST, [this]() {\n    g_settings.streamEnabled = true;\n    restartStreaming();\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  _server.on(\"/api/stream/stop\", HTTP_POST, [this]() {\n    g_settings.streamEnabled = false;\n    StreamClient::instance().stop();\n    AudioRingBuffer::instance().clear();\n    g_receiverState = RX_STOPPED;\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  _server.on(\"/api/stream/reconnect\", HTTP_POST, [this]() {\n    restartStreaming();\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  _server.on(\"/api/wifi/reconnect\", HTTP_POST, [this]() {\n    WiFi.disconnect();\n    WiFi.begin(DEFAULT_WIFI_SSID, DEFAULT_WIFI_PASS);\n    sendJsonResponse(200, \"{\\\"ok\\\":true}\");\n  });\n\n  _server.on(\"/api/system/reboot\", HTTP_POST, [this]() {\n    sendJsonResponse(200, \"{\\\"ok\\\":true,\\\"message\\\":\\\"Rebooting\\\"}\");\n    delay(200);\n    ESP.restart();\n  });\n\n  // OTA Firmware Upload\n  _server.on(\"/api/ota\", HTTP_POST, [this]() {\n    if (_otaFailed) {\n      sendJsonResponse(500, \"{\\\"ok\\\":false,\\\"error\\\":\\\"\" + _otaError + \"\\\"}\");\n    } else {\n      sendJsonResponse(200, \"{\\\"ok\\\":true,\\\"message\\\":\\\"Update complete\\\"}\");\n      delay(500);\n      ESP.restart();\n    }\n  }, [this]() {\n    handleFirmwareUpload();\n  });\n}\n",
  "src/main.cpp": "/*\n  =============================================================================\n  C3 Music Receiver (Modular PlatformIO Architecture)\n  Hardware: ESP32-C3 SuperMini + SSD1306 0.42\" OLED + UDA1334A I2S DAC\n  Web UI: Material Design 3 Minimal AMOLED App\n  Audio: Port 50005 (Raw PCM) + Port 8080 (HTTP WAV)\n  =============================================================================\n*/\n\n#include \"config.h\"\n#include \"audio_i2s.h\"\n#include \"audio_ringbuf.h\"\n#include \"stream_client.h\"\n#include \"display_oled.h\"\n#include \"web_server.h\"\n\n#include <WiFi.h>\n#include <Preferences.h>\n\n// Global System Objects\nAppSettings g_settings;\nRuntimeStats g_stats;\nPreferences g_preferences;\nvolatile ReceiverState g_receiverState = RX_BOOTING;\nvolatile bool g_bufferStarted = false;\nvolatile bool g_stopRequested = false;\n\nTaskHandle_t g_playbackTaskHandle = nullptr;\nTaskHandle_t g_streamTaskHandle = nullptr;\n\nuint32_t g_lastWifiAttemptMs = 0;\nuint32_t g_lastStreamAttemptMs = 0;\n\nvoid loadPreferences() {\n  g_preferences.begin(\"c3music\", false);\n  g_settings.phoneHost = g_preferences.getString(\"host\", DEFAULT_PHONE_HOST);\n  g_settings.tcpPort = g_preferences.getUShort(\"tcpport\", DEFAULT_TCP_PORT);\n  g_settings.httpPort = g_preferences.getUShort(\"httpport\", DEFAULT_HTTP_PORT);\n  g_settings.preferredMode = (StreamMode)g_preferences.getUChar(\"mode\", STREAM_MODE_TCP);\n  g_settings.autoFallback = g_preferences.getBool(\"fallback\", true);\n  g_settings.autoReconnect = g_preferences.getBool(\"autorecon\", true);\n  g_settings.oledEnabled = g_preferences.getBool(\"oled\", true);\n  g_settings.streamEnabled = g_preferences.getBool(\"enabled\", true);\n  g_settings.targetBufferMs = g_preferences.getUShort(\"buffer\", 180);\n}\n\nvoid savePreferences() {\n  g_preferences.putString(\"host\", g_settings.phoneHost);\n  g_preferences.putUShort(\"tcpport\", g_settings.tcpPort);\n  g_preferences.putUShort(\"httpport\", g_settings.httpPort);\n  g_preferences.putUChar(\"mode\", g_settings.preferredMode);\n  g_preferences.putBool(\"fallback\", g_settings.autoFallback);\n  g_preferences.putBool(\"autorecon\", g_settings.autoReconnect);\n  g_preferences.putBool(\"oled\", g_settings.oledEnabled);\n  g_preferences.putBool(\"enabled\", g_settings.streamEnabled);\n  g_preferences.putUShort(\"buffer\", g_settings.targetBufferMs);\n}\n\nvoid restartStreaming() {\n  g_stopRequested = true;\n  StreamClient::instance().stop();\n  AudioRingBuffer::instance().clear();\n  delay(50);\n  g_stopRequested = false;\n  g_bufferStarted = false;\n  g_lastStreamAttemptMs = 0;\n  g_receiverState = RX_IDLE;\n}\n\n// FreeRTOS Task: Streams PCM samples from ring buffer directly to I2S DAC FIFO\nvoid playbackTask(void*) {\n  uint8_t readBuffer[I2S_DMA_CHUNK];\n\n  for (;;) {\n    if (!AudioI2S::instance().isReady() || !g_bufferStarted) {\n      vTaskDelay(pdMS_TO_TICKS(10));\n      continue;\n    }\n\n    size_t bytesRead = AudioRingBuffer::instance().read(readBuffer, sizeof(readBuffer));\n    if (bytesRead == 0) {\n      g_stats.underruns++;\n      xSemaphoreTake(AudioRingBuffer::instance().dataSemaphore(), pdMS_TO_TICKS(20));\n      continue;\n    }\n\n    StreamFormat fmt = StreamClient::instance().currentFormat();\n    if (fmt.channels == 1) {\n      AudioI2S::instance().writeMonoAsStereo(readBuffer, bytesRead, 40);\n      g_stats.bytesPlayed += (bytesRead / 2);\n    } else {\n      AudioI2S::instance().writeSamples(readBuffer, bytesRead, 40);\n      g_stats.bytesPlayed += bytesRead;\n    }\n  }\n}\n\n// FreeRTOS Task: Connects to Android Streamer & pumps incoming audio into Ring Buffer\nvoid streamTask(void*) {\n  for (;;) {\n    if (WiFi.status() != WL_CONNECTED) {\n      StreamClient::instance().stop();\n      AudioRingBuffer::instance().clear();\n      g_receiverState = RX_WIFI_OFFLINE;\n      vTaskDelay(pdMS_TO_TICKS(500));\n      continue;\n    }\n\n    if (!g_settings.streamEnabled || g_stopRequested) {\n      StreamClient::instance().stop();\n      AudioRingBuffer::instance().clear();\n      if (g_receiverState != RX_STOPPED) g_receiverState = RX_STOPPED;\n      vTaskDelay(pdMS_TO_TICKS(150));\n      continue;\n    }\n\n    if (!StreamClient::instance().isConnected()) {\n      if (millis() - g_lastStreamAttemptMs < STREAM_RETRY_INTERVAL_MS) {\n        vTaskDelay(pdMS_TO_TICKS(20));\n        continue;\n      }\n      g_lastStreamAttemptMs = millis();\n      g_receiverState = RX_CONNECTING;\n\n      bool connected = false;\n      if (g_settings.preferredMode == STREAM_MODE_TCP) {\n        connected = StreamClient::instance().connectTcp(g_settings.phoneHost, g_settings.tcpPort);\n        if (!connected && g_settings.autoFallback) {\n          connected = StreamClient::instance().connectHttp(g_settings.phoneHost, g_settings.httpPort);\n        }\n      } else {\n        connected = StreamClient::instance().connectHttp(g_settings.phoneHost, g_settings.httpPort);\n        if (!connected && g_settings.autoFallback) {\n          connected = StreamClient::instance().connectTcp(g_settings.phoneHost, g_settings.tcpPort);\n        }\n      }\n\n      if (connected) {\n        g_stats.reconnects++;\n        g_stats.sessionStartedMs = millis();\n        AudioRingBuffer::instance().clear();\n        g_bufferStarted = false;\n        g_receiverState = RX_BUFFERING;\n      } else {\n        g_stats.streamErrors++;\n        g_receiverState = RX_ERROR;\n        vTaskDelay(pdMS_TO_TICKS(1000));\n        continue;\n      }\n    }\n\n    StreamClient::instance().processStream();\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(300);\n  Serial.println(\"\\n\\n========================================================\");\n  Serial.printf(\" %s v%s\\n\", DEVICE_NAME, FIRMWARE_VERSION);\n  Serial.println(\"========================================================\");\n\n  loadPreferences();\n\n  // 1. OLED Display\n  DisplayOLED::instance().setEnabled(g_settings.oledEnabled);\n  DisplayOLED::instance().begin();\n\n  // 2. Hardware I2S + 440Hz Test Beep to confirm DAC\n  AudioI2S::instance().begin(DEFAULT_SAMPLE_RATE, DEFAULT_CHANNELS);\n  AudioI2S::instance().playTestTone(400);\n\n  // 3. Wi-Fi (Disable sleep for minimum audio latency)\n  WiFi.mode(WIFI_STA);\n  WiFi.setSleep(false);\n  WiFi.setAutoReconnect(true);\n  WiFi.begin(DEFAULT_WIFI_SSID, DEFAULT_WIFI_PASS);\n  Serial.printf(\"[WIFI] Connecting to %s...\\n\", DEFAULT_WIFI_SSID);\n\n  // 4. Start Web Server\n  WebServerManager::instance().begin();\n\n  // 5. Create FreeRTOS Real-Time Tasks\n  xTaskCreate(playbackTask, \"i2s_playback\", 4096, nullptr, 3, &g_playbackTaskHandle);\n  xTaskCreate(streamTask,   \"net_stream\",   6144, nullptr, 2, &g_streamTaskHandle);\n\n  Serial.println(\"[SYSTEM] Setup complete. Ready.\");\n}\n\nvoid loop() {\n  WebServerManager::instance().handleClient();\n\n  if (WiFi.status() == WL_CONNECTED) {\n    WebServerManager::instance().beginMdnsIfNeeded();\n  } else {\n    if (millis() - g_lastWifiAttemptMs > WIFI_RETRY_INTERVAL_MS) {\n      g_lastWifiAttemptMs = millis();\n      WiFi.reconnect();\n    }\n  }\n\n  // Update 0.42\" OLED screen\n  DisplayOLED::instance().update(\n    g_receiverState,\n    StreamClient::instance().currentFormat(),\n    AudioRingBuffer::instance().percentFull(),\n    g_stats.lastError\n  );\n\n  delay(2);\n}\n"
};
